test_that("ERA5 request fields are exact", { cfg<-list(cds=list(dataset_short_name="derived-era5-single-levels-daily-statistics",product_type="reanalysis",variable="2m_temperature",daily_statistic="daily_minimum",time_zone="utc+00:00",frequency="6_hourly",data_format="netcdf",download_format="unarchived")); x<-build_era5_mintemp_requests(as.Date(c("2026-07-01","2026-07-03")),c(40.25,-125.25,-.25,-34.75),cfg)[[1]]; expect_equal(x$variable,"2m_temperature"); expect_equal(x$daily_statistic,"daily_minimum"); expect_false("user"%in%names(x)); expect_equal(x$day,c("01","03")) })
